from llguidance.gbnf_to_lark import GrammarParser, resolve, AlternativeNode, SequenceNode, RuleRefNode, LiteralNode, RegexNode, RepetitionNode
p = GrammarParser()
rules = p.parse(open('resources/ground_truth/json_ws.gbnf').read())
resolve(rules)

def describe(node, indent=0):
    prefix = '  ' * indent
    if isinstance(node, AlternativeNode):
        print(f'{prefix}AlternativeNode({len(node.alternatives)} arms)')
        for i, a in enumerate(node.alternatives):
            print(f'{prefix}  [{i}]')
            describe(a, indent+2)
    elif isinstance(node, SequenceNode):
        print(f'{prefix}SequenceNode({len(node.nodes)} nodes)')
        for n in node.nodes:
            describe(n, indent+1)
    elif isinstance(node, RuleRefNode):
        print(f'{prefix}RuleRefNode({node.name!r})')
    elif isinstance(node, LiteralNode):
        print(f'{prefix}LiteralNode({node.value!r})')
    elif isinstance(node, RegexNode):
        print(f'{prefix}RegexNode({node.rx!r})')
    elif isinstance(node, RepetitionNode):
        print(f'{prefix}RepetitionNode({node.min_times},{node.max_times})')
        describe(node.node, indent+1)
    else:
        print(f'{prefix}{type(node).__name__}')

print('=== value rule ===')
describe(rules['value'].alternatives)
